import math


def _validate_config(patience, delta):
    try:
        valid_patience = patience >= 1
        valid_delta = delta >= 0 and math.isfinite(delta)
    except (TypeError, ValueError, OverflowError):
        raise ValueError('config') from None
    if not valid_patience or not valid_delta:
        raise ValueError('config')


def advance(state, value, index, patience, delta):
    _validate_config(patience, delta)
    try:
        finite_value = math.isfinite(value)
    except (TypeError, ValueError, OverflowError):
        raise ValueError('value') from None
    if not finite_value:
        raise ValueError('value')

    out = dict(state)
    if out['best'] is None or value < out['best'] - delta:
        out.update(best=value, best_index=index, stale=0)
    else:
        out['stale'] += 1
    out['seen'] += 1
    out['stopped'] = out['stale'] >= patience
    return out

from core import advance, _validate_config


def solve(p):
    _validate_config(p['patience'], p['delta'])
    supplied = p['state']
    s = dict(supplied) if supplied is not None else {
        'best': None,
        'best_index': -1,
        'stale': 0,
        'seen': 0,
        'stopped': False,
    }
    for v in p['values']:
        if s['stopped']:
            break
        s = advance(s, v, s['seen'], p['patience'], p['delta'])
    return s
